from textual.app import App, ComposeResult
from textual.message import Message
from textual.widgets import Button, Static, Label
from textual.containers import Container


class MyWidget(Static):
    """Custom widget that sends messages to its parent."""

    class SubmitPressed(Message):
        """Message sent when submit button is pressed."""
        def __init__(self, value: str) -> None:
            self.value = value
            super().__init__()

    def compose(self) -> ComposeResult:
        yield Button("Submit")

    def on_button_pressed(self, event: Button.Pressed) -> None:
        """Send custom message to parent when button is clicked."""
        self.post_message(self.SubmitPressed("Button clicked!"))


class MyApp(App):
    """Main application."""

    def compose(self) -> ComposeResult:
        yield Container(
            Label("Click the button:"),
            MyWidget(),
        )

    def on_submit_pressed(self, message: MyWidget.SubmitPressed) -> None:
        """Handle the custom message from MyWidget."""
        self.title = f"Status: {message.value}"


if __name__ == "__main__":
    MyApp().run()

